import { t as supabase } from "./client-C0cJttI-.js";
import { useEffect } from "react";
import { useNavigate } from "@tanstack/react-router";
import { jsx, jsxs } from "react/jsx-runtime";
import { toast } from "sonner";
//#region src/routes/auth/callback.tsx?tsr-split=component
function AuthCallbackComponent() {
	const navigate = useNavigate();
	useEffect(() => {
		const handleCallback = async () => {
			try {
				const { data: { session }, error } = await supabase.auth.getSession();
				if (error) throw error;
				if (session) {
					toast.success("Login realizado com sucesso!");
					navigate({
						to: "/painel",
						replace: true
					});
				} else {
					toast.error("Falha ao validar sessão. Tente novamente.");
					navigate({
						to: "/auth",
						replace: true
					});
				}
			} catch (err) {
				console.error("Erro no callback:", err);
				toast.error("Erro durante o processamento do login.");
				navigate({
					to: "/auth",
					replace: true
				});
			}
		};
		handleCallback();
	}, [navigate]);
	return /* @__PURE__ */ jsx("div", {
		className: "flex min-h-screen items-center justify-center bg-surface text-primary",
		children: /* @__PURE__ */ jsxs("div", {
			className: "flex flex-col items-center gap-4",
			children: [/* @__PURE__ */ jsx("div", { className: "h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" }), /* @__PURE__ */ jsx("p", {
				className: "font-display text-sm uppercase tracking-widest",
				children: "Processando autenticação..."
			})]
		})
	});
}
//#endregion
export { AuthCallbackComponent as component };
